# owner: platform
"""Short absence notes to send home to parents."""

from typing import List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date

def check_ownership(
    student: Student, marks: List[Mark]
) -> None:
    others = {mark.student_id for mark in marks}
    others.discard(student.student_id)
    if others:
        listed = ", ".join(sorted(others))
        raise ValueError(f"marks for other ids: {listed}")

def absent_days(marks: List[Mark]) -> List[date]:
    missed = sorted(set(days_missed(marks)))
    if not missed:
        raise ValueError("no absences to write about")
    return missed

def format_day(missed_day: date) -> str:
    month = missed_day.strftime("%B")
    return f"{month} {missed_day.day}, {missed_day.year}"

def render_notice(
    student: Student, missed: List[date]
) -> str:
    days = "day" if len(missed) == 1 else "days"
    dates = "; ".join(format_day(item) for item in missed)
    head = f"{student.first_name} {student.last_name}"
    body = f"was absent {len(missed)} {days}: {dates}."
    return f"Dear parent or guardian,\n\n{head} {body}\n"

def absence_notice(
    student: Student, marks: List[Mark]
) -> str:
    """Parent note listing each absent day."""
    check_ownership(student, marks)
    return render_notice(student, absent_days(marks))
